fn is_palindrome(text: Vec<char>) -> bool {
    // Requires that the input vector is not empty
    // Ensures that the function returns true if the input is a palindrome, false otherwise
    // The length of the input vector is invariant during the loop
    // The loop decreases the remaining characters to check
    // The function is specified to work with characters in a case-insensitive manner

    // Requires: text.len() >= 0
    // Ensures: (forall i: usize, 0 <= i && i < text.len() / 2 ==> 
    //            text[i].to_ascii_lowercase() == text[text.len() - 1 - i].to_ascii_lowercase()) 
    //          ==> is_palindrome(text) == true
    //          && (exists i: usize, 0 <= i && i < text.len() / 2 ==> 
    //            text[i].to_ascii_lowercase() != text[text.len() - 1 - i].to_ascii_lowercase()) 
    //          ==> is_palindrome(text) == false

    let len = text.len();
    // Invariant: 0 <= i && i < len / 2
    for i in 0..len / 2 {
        let left_char = text[i];
        let right_char = text[len - 1 - i];

        // Assert that the characters being compared are within bounds
        assert!(i < len / 2);
        assert!(len - 1 - i < len);

        if left_char.to_ascii_lowercase() != right_char.to_ascii_lowercase() {
            return false;
        }
    }
    true
}